import { describe, expect, test } from "vitest"

import { isAnimatedAvif, isAnimatedPng } from "./container-animation.js"

const ANIMATED_APNG = ""
const ANIMATED_AVIF = ""

describe("xlchemy container animation parsers", () => {
  test("detects APNG by its acTL chunk", () => {
    expect(isAnimatedPng(Buffer.from(ANIMATED_APNG, "base64"))).toBe(true)
    expect(isAnimatedPng(staticPng())).toBe(false)
  })

  test("detects animated AVIF by its sequence brand", () => {
    expect(isAnimatedAvif(Buffer.from(ANIMATED_AVIF, "base64"))).toBe(true)
    expect(isAnimatedAvif(staticAvif())).toBe(false)
  })
})

function staticPng(): Uint8Array {
  return Buffer.from("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=", "base64")
}

function staticAvif(): Uint8Array {
  const bytes = Buffer.alloc(20)
  bytes.writeUInt32BE(20, 0)
  bytes.write("ftypavif", 4, "ascii")
  bytes.writeUInt32BE(0, 12)
  bytes.write("mif1", 16, "ascii")
  return bytes
}
